import re
text = open('.godot/global_script_class_cache.cfg').read()
entries = re.findall(r'\{[^{}]*\}', text)
seen = {}
for e in entries:
    m = re.search(r'\"class\": &\"(\w+)\"', e)
    p = re.search(r'\"path\": \"([^\"]+)\"', e)
    if m:
        seen.setdefault(m.group(1), []).append(p.group(1) if p else '?')
for k, v in seen.items():
    if len(v) > 1:
        print(k, v)
